using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Structure;

var doc = Document;
// setup: a structural framing symbol (braces use the framing family) and the lowest level
var symbol = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFraming).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First();
var level  = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
// a diagonal line -- a brace rises from one point to another
var line = Line.CreateBound(new XYZ(0, 20, 0), new XYZ(10, 20, 10));

ElementId braceId = null;
Connector.WithTransaction(doc, () => {
    if (!symbol.IsActive) symbol.Activate();
    var brace = doc.Create.NewFamilyInstance(line, symbol, level, StructuralType.Brace);
    braceId = brace.Id;
});

var created = (FamilyInstance)doc.GetElement(braceId);
return new { braceId = braceId.ToString(), symbol = symbol.Name, level = level.Name, structuralType = created.StructuralType.ToString(), category = created.Category?.Name };
